def next_smallest_palindrome(n: int) -> int:
    """
    Return the smallest palindrome strictly greater than the input integer n.
    """
    # Convert number to string for easier manipulation
    s = str(n)

    length = len(s)
    half = (length + 1) // 2  # Midpoint, leaning right for odd length

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Special case: if all digits are '9', next palindrome is 10..01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Construct palindrome by mirroring the left half to right
    # For odd length, the middle digit belongs to the left half
    left_half = s[:half]
    if length % 2 == 0:
        palindrome = left_half + left_half[::-1]
    else:
        palindrome = left_half + left_half[:-1][::-1]

    if int(palindrome) > n:
        return int(palindrome)

    # If palindrome <= n, we need to increment the left half and mirror again
    # Increment the left half as an integer
    left_num = int(left_half)
    left_num += 1
    left_half = str(left_num)

    # If increment increased length of left_half (e.g. 999 -> 1000)
    if len(left_half) > half:
        # This happens when the increment causes a carry that increases digit count
        # The palindrome becomes of the form 100...001 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    if length % 2 == 0:
        palindrome = left_half + left_half[::-1]
    else:
        palindrome = left_half + left_half[:-1][::-1]

    return int(palindrome)

def find_solution(a, b, n):
    # We look for non-negative integer x starting from 0 upwards,
    # such that (n - a*x) is divisible by b and the quotient y is non-negative.
    if a == 0 and b == 0:
        # Equation reduces to 0 = n; solution only if n == 0
        return (0, 0) if n == 0 else 'No solution'
    if a == 0:
        # Equation: b*y = n
        if b == 0:
            return 'No solution'
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return 'No solution'
    if b == 0:
        # Equation: a*x = n
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return 'No solution'

    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1
    return 'No solution'

