    length = len(text)
    for i in range(length - 3):  # need at least 4 chars to check 'a' + 3 times 'b'
        first_char = text[i]
        # Check exactly 2 repetitions of next char
        if i + 3 < length:
            second_char = text[i + 1]
            if (text[i + 2] == second_char and text[i + 3] != second_char and first_char != second_char):
                return True
        # Check exactly 3 repetitions of next char
        if i + 4 < length:
            second_char = text[i + 1]
            if (text[i + 2] == second_char and text[i + 3] == second_char and text[i + 4] != second_char and first_char != second_char):
                return True
    # Edge case: check the last possible triple 'abb' at the end
    # if string ends with exactly 3 chars, check if they match 'abb'
    if length >= 3:
        for i in range(length - 2):
            first_char = text[i]
            second_char = text[i + 1]
            if (first_char != second_char and
                text[i + 2] == second_char):
