def find_solution(a: int, b: int, n: int):
    """
    Finds the first non-negative integer x starting from 0 such that there exists an integer y
    satisfying a*x + b*y = n. Returns a tuple (x, y) if solution exists, else None.
    """
    if b == 0:
        # Then equation is a*x = n, so y can be any integer only if b=0, but since b=0,
        # y is irrelevant. Check if n divisible by a and x non-negative integer.
        if a == 0:
            # a and b both zero means equation is 0 = n; only solution if n == 0
            return (0, 0) if n == 0 else None
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
            else:
                return None
        else:
            return None

    # General case: For x >= 0, check if (n - a*x) divisible by b to get integer y
    x = 0
    # To prevent infinite loop, consider limits on x:
    # Since no domain limits given, we can scan indefinitely.
    # But to avoid infinite loops, we can set a reasonable upper bound.
    # Assume search up to abs(n) + 1 or some limit (or until no solution).
    # Because if a and b are positive, and x gets too large, n - a*x becomes negative.
    # We can scan up to a limit.
    max_iter = abs(n) + 1 if n != 0 else 1000
    # If a == 0, then equation reduces to b*y = n, so y = n/b if divisible, x = 0 is fixed.
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return None

    while x <= max_iter:
        remainder = n - a * x
        if b != 0 and remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1

    return None

