    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1  # sequences of length 1 ending with x

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each possible next element y, sum all dp[x] where x <= y/2 (since y >= 2*x)
        # For efficiency, we precompute prefix sums of dp
        prefix_sum = [0] * (m + 1)
        for x in range(1, m + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp[x]

        for y in range(1, m + 1):
            # y must be >= 2 * prev => prev <= y//2
            max_prev = y // 2
            if max_prev >= 1:
                new_dp[y] = prefix_sum[max_prev]
