def find_Max(nums):
    if not nums:
        return None

    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            # Max must be in [mid, right]
            left = mid
        elif nums[mid] < nums[right]:
            # Max is in [left, mid]
            right = mid
        else:
            # nums[mid] == nums[right], duplicates, can't decide, reduce right
            right -= 1
    return nums[left]

