def substract_elements(coll):
    """
    Recursively subtract numeric leaf values found in the nested collection.
    The subtraction is performed as:
        first_leaf_value - sum_of_all_other_leaf_values
    If no leaves are found, return 0.

    Supported containers: list, tuple, set, dict (values).
    Leaves are assumed to be numeric (int or float).
    """
    def gather_leaves(c):
        if isinstance(c, (int, float)):
            return [c]
        elif isinstance(c, dict):
            leaves = []
            for v in c.values():
                leaves.extend(gather_leaves(v))
            return leaves
        elif isinstance(c, (list, tuple, set)):
            leaves = []
            for item in c:
                leaves.extend(gather_leaves(item))
            return leaves
        else:
            # If a non-collection non-numeric leaf occurs, per user answer, this is not expected.
            # So we don't handle it explicitly.
            return []

    leaves = gather_leaves(coll)
    if not leaves:
        return 0
    first, *rest = leaves
    return first - sum(rest)

def get_noOfways(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    # dp[i] = number of ways to tile 2 x i board with 2 x 1 dominoes
    dp = [0] * (n + 1)
    dp[0] = 0  # as per user clarification
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

