def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Increment the numeric string by 1
    def increment_str_num(x: str) -> str:
        return str(int(x) + 1)

    # Generate palindrome by mirroring left half to right half
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # If input is less than 9, next palindrome is n+1 (because single digit palindromes are digits)
    if n < 9:
        return n + 1

    # Main logic:
    # 1. Split the number into left half, middle (if odd), and right half
    # 2. Construct palindrome by mirroring left half
    # 3. If palindrome <= n, increment the middle part and mirror again

    odd = (length % 2 != 0)
    half_len = (length + 1) // 2  # Length of left half including middle if odd

    left_half = s[:half_len]
    # Generate palindrome candidate
    candidate = make_palindrome(left_half, odd)

    if int(candidate) > n:
        return int(candidate)

    # Need to increment the left half and then mirror again

    # Increment left half as an integer string
    incremented_left = str(int(left_half) + 1)

    # If incrementing left half changes length (like 999 -> 1000)
    # then palindrome length increases by 1 (e.g., 999 -> 1001)
    if len(incremented_left) > len(left_half):
        # This happens when all digits in left half are '9's.
        # New palindrome is 1 followed by zeros and ending with 1
        return int("1" + ("0" * (length - 1)) + "1")

    # Otherwise construct palindrome with incremented left half
    candidate = make_palindrome(incremented_left, odd)
    return int(candidate)

def next_power_of_2(n: int) -> int:
    if n <= 0:
        return 1
    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
