def get_noOfways(m: int, n: int) -> int:
    if m != 2:
        raise ValueError("This function only supports tiling a 2 x n board (m must be 2).")
    if n < 0:
        raise ValueError("Length n must be non-negative.")
    # Base cases
    if n == 0:
        return 1  # empty board, one way (do nothing)
    if n == 1:
        return 1  # only vertical tile

    # dp[i] = number of ways to tile 2 x i board
    dp0, dp1 = 1, 1
    for i in range(2, n + 1):
        dp0, dp1 = dp1, dp0 + dp1

    return dp1
